import pyomo.environ as pyo

DATA = {
    "products": ["I", "II", "III"],
    "resources": ["A", "B", "C"],
    # unit product profit (thousands) per product
    "profit": {"I": 3.0, "II": 2.0, "III": 2.9},
    # resource usage per unit of each product
    "usage": {
        "A": {"I": 8, "II": 2, "III": 10},
        "B": {"I": 10, "II": 5, "III": 8},
        "C": {"I": 2, "II": 13, "III": 10},
    },
    # monthly device capacity
    "capacity": {"A": 300, "B": 400, "C": 420},
}


def build_model(data=None):
    d = data or DATA
    m = pyo.ConcreteModel()

    m.P = pyo.Set(initialize=d["products"], ordered=True)
    m.R = pyo.Set(initialize=d["resources"], ordered=True)

    def x_bounds(m, p):
        return (0, None)

    m.x = pyo.Var(m.P, bounds=x_bounds, within=pyo.NonNegativeReals)

    def profit_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    m.obj = pyo.Objective(rule=profit_rule, sense=pyo.maximize)

    def capacity_rule(m, r):
        return sum(d["usage"][r][p] * m.x[p] for p in m.P) <= d["capacity"][r]

    m.capacity_c = pyo.Constraint(m.R, rule=capacity_rule)

    return m
